// Some portions generated by Claude
package org.eclipse.rdf4j.sail.lmdb;

import static org.assertj.core.api.Assertions.assertThat;

import org.eclipse.rdf4j.model.impl.SimpleValueFactory;
import org.eclipse.rdf4j.query.algebra.Distinct;
import org.eclipse.rdf4j.query.algebra.Exists;
import org.eclipse.rdf4j.query.algebra.Filter;
import org.eclipse.rdf4j.query.algebra.Join;
import org.eclipse.rdf4j.query.algebra.Projection;
import org.eclipse.rdf4j.query.algebra.ProjectionElem;
import org.eclipse.rdf4j.query.algebra.ProjectionElemList;
import org.eclipse.rdf4j.query.algebra.StatementPattern;
import org.eclipse.rdf4j.query.algebra.Var;
import org.eclipse.rdf4j.query.impl.EmptyBindingSet;
import org.junit.jupiter.api.Test;

/** A witness may only replace a lookup the planned join order would have run last. */
class LmdbDistinctWitnessOptimizerTest {

	/** {@code SELECT DISTINCT ?s ?o { ?s :rare ?x . ?s :common ?o }} planned as [rare, common]. */
	@Test
	void leadingSelectivePatternStaysTheJoinDriver() {
		var rare = pattern("s", "urn:rare", "x");
		var common = pattern("s", "urn:common", "o");
		var join = new Join(rare, common);
		var projection = projection(join, "s", "o");

		optimize(projection);

		assertThat(projection.getArg()).isSameAs(join);
		assertThat(join.getLeftArg()).isSameAs(rare);
		assertThat(join.getRightArg()).isSameAs(common);
	}

	/** The same query planned as [common, rare]: the hidden fan-out is probed where its lookup would have run. */
	@Test
	void trailingHiddenFanOutBecomesAWitness() {
		var common = pattern("s", "urn:common", "o");
		var rare = pattern("s", "urn:rare", "x");
		var projection = projection(new Join(common, rare), "s", "o");

		optimize(projection);

		assertThat(projection.getArg()).isInstanceOf(Filter.class);
		var filter = (Filter) projection.getArg();
		assertThat(filter.getArg()).isSameAs(common);
		assertThat(filter.getCondition()).isInstanceOf(Exists.class);
		assertThat(((Exists) filter.getCondition()).getSubQuery()).isSameAs(rare);
	}

	/** Planned as [first, hidden, fanOut]: a filter above the group would move the hidden lookup behind the fan-out. */
	@Test
	void hiddenPatternBeforeALaterProducerStaysInTheJoin() {
		var first = pattern("s", "urn:first", "o");
		var hidden = pattern("s", "urn:hidden", "x");
		var fanOut = pattern("o", "urn:fanOut", "z");
		var inner = new Join(hidden, fanOut);
		var join = new Join(first, inner);
		var projection = projection(join, "s", "o", "z");

		optimize(projection);

		assertThat(projection.getArg()).isSameAs(join);
		assertThat(join.getLeftArg()).isSameAs(first);
		assertThat(join.getRightArg()).isSameAs(inner);
		assertThat(inner.getLeftArg()).isSameAs(hidden);
		assertThat(inner.getRightArg()).isSameAs(fanOut);
	}

	private static void optimize(Projection projection) {
		new LmdbDistinctWitnessOptimizer().optimize(new Distinct(projection), null, EmptyBindingSet.getInstance());
	}

	private static Projection projection(Join join, String... names) {
		var elements = new ProjectionElemList();
		for (String name : names) {
			elements.addElement(new ProjectionElem(name));
		}
		return new Projection(join, elements);
	}

	private static StatementPattern pattern(String subject, String predicate, String object) {
		return new StatementPattern(Var.of(subject),
				Var.of("_const_" + predicate, SimpleValueFactory.getInstance().createIRI(predicate), true, true),
				Var.of(object));
	}
}
